-- SQL script to create tables for PEZA SCMS

CREATE DATABASE IF NOT EXISTS peza_scms CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE peza_scms;

CREATE TABLE IF NOT EXISTS companies (
    company_id INT AUTO_INCREMENT PRIMARY KEY,
    company_name VARCHAR(255) NOT NULL,
    category VARCHAR(100) DEFAULT NULL,
    status VARCHAR(20) DEFAULT 'Active',
    remarks TEXT,
    last_updated TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP
) ENGINE=InnoDB;

CREATE TABLE IF NOT EXISTS officers (
    officer_id INT AUTO_INCREMENT PRIMARY KEY,
    company_id INT NOT NULL,
    officer_name VARCHAR(255) NOT NULL,
    position VARCHAR(100) DEFAULT NULL,
    email VARCHAR(255) DEFAULT NULL,
    phone VARCHAR(50) DEFAULT NULL,
    FOREIGN KEY (company_id) REFERENCES companies(company_id) ON DELETE CASCADE
) ENGINE=InnoDB;

-- optional users table for storing administrator credentials
CREATE TABLE IF NOT EXISTS users (
    user_id INT AUTO_INCREMENT PRIMARY KEY,
    username VARCHAR(100) NOT NULL UNIQUE,
    password_hash VARCHAR(255) NOT NULL
) ENGINE=InnoDB;

CREATE TABLE IF NOT EXISTS rfq (
    rfq_id INT AUTO_INCREMENT PRIMARY KEY,
    rfq_number VARCHAR(50) UNIQUE NOT NULL,
    recipient_name VARCHAR(255) NOT NULL,
    recipient_address TEXT DEFAULT NULL,
    rfq_date DATE NOT NULL,
    submission_deadline DATE NOT NULL,
    rfq_description TEXT DEFAULT NULL,
    delivery_period VARCHAR(50) DEFAULT NULL,
    bidder_documents TEXT DEFAULT NULL,
    supplier_full_name VARCHAR(255) DEFAULT NULL,
    supplier_designation VARCHAR(255) DEFAULT NULL,
    supplier_company VARCHAR(255) DEFAULT NULL,
    supplier_contact_no VARCHAR(100) DEFAULT NULL,
    supplier_address TEXT DEFAULT NULL,
    bac_chair VARCHAR(255) DEFAULT NULL,
    status VARCHAR(50) DEFAULT 'Draft',
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    KEY (rfq_number),
    KEY (status)
) ENGINE=InnoDB;

CREATE TABLE IF NOT EXISTS rfq_items (
    item_id INT AUTO_INCREMENT PRIMARY KEY,
    rfq_id INT NOT NULL,
    item_number INT NOT NULL,
    quantity DECIMAL(10,2) NOT NULL,
    unit VARCHAR(50) NOT NULL,
    articles VARCHAR(255) NOT NULL,
    unit_price DECIMAL(12,2) DEFAULT 0,
    total_cost DECIMAL(12,2) GENERATED ALWAYS AS (quantity * unit_price) STORED,
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    KEY (rfq_id),
    UNIQUE KEY unique_item_number (rfq_id, item_number),
    FOREIGN KEY (rfq_id) REFERENCES rfq(rfq_id) ON DELETE CASCADE
) ENGINE=InnoDB;

CREATE TABLE IF NOT EXISTS market_scoping_checklist (
    checklist_id INT AUTO_INCREMENT PRIMARY KEY,
    scoping_id INT NULL,
    consultation TINYINT(1) DEFAULT 0,
    conferences TINYINT(1) DEFAULT 0,
    technical_reports TINYINT(1) DEFAULT 0,
    publications TINYINT(1) DEFAULT 0,
    price_sourcing TINYINT(1) DEFAULT 0,
    philgeps TINYINT(1) DEFAULT 0,
    other_activity_checkbox TINYINT(1) DEFAULT 0,
    other_activity TEXT DEFAULT NULL,
    documents VARCHAR(255) DEFAULT NULL,
    cost_estimate_considered ENUM('Yes','No','Not Applicable') DEFAULT 'Not Applicable',
    cost_estimate_recommendation TEXT DEFAULT NULL,
    design_spec_considered ENUM('Yes','No','Not Applicable') DEFAULT 'Not Applicable',
    design_spec_recommendation TEXT DEFAULT NULL,
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    FOREIGN KEY (scoping_id) REFERENCES market_scoping(scoping_id) ON DELETE SET NULL
) ENGINE=InnoDB;

CREATE TABLE IF NOT EXISTS market_scoping (
    scoping_id INT AUTO_INCREMENT PRIMARY KEY,
    procuring_entity VARCHAR(255) NOT NULL DEFAULT 'Philippine Economic Zone Authority',
    end_user_unit VARCHAR(255) DEFAULT NULL,
    representative_name VARCHAR(255) DEFAULT NULL,
    designation VARCHAR(255) DEFAULT NULL,
    project_name VARCHAR(255) NOT NULL,
    item_quantity INT DEFAULT 1,
    item_unit VARCHAR(50) DEFAULT 'unit',
    category VARCHAR(50) DEFAULT 'Other',
    estimated_budget DECIMAL(14,2) DEFAULT NULL,
    period_from_month TINYINT DEFAULT NULL,
    period_from_year SMALLINT DEFAULT NULL,
    period_to_month TINYINT DEFAULT NULL,
    period_to_year SMALLINT DEFAULT NULL,
    expected_delivery_month TINYINT DEFAULT NULL,
    expected_delivery_year SMALLINT DEFAULT NULL,
    expected_delivery_date DATE DEFAULT NULL,
    supplier_id INT DEFAULT NULL,
    quotation DECIMAL(13,2) DEFAULT NULL,
    supplier_id_1 INT DEFAULT NULL,
    quotation_1 DECIMAL(13,2) DEFAULT NULL,
    supplier_id_2 INT DEFAULT NULL,
    quotation_2 DECIMAL(13,2) DEFAULT NULL,
    supplier_id_3 INT DEFAULT NULL,
    quotation_3 DECIMAL(13,2) DEFAULT NULL,
    supplier_id_4 INT DEFAULT NULL,
    quotation_4 DECIMAL(13,2) DEFAULT NULL,
    supplier_id_5 INT DEFAULT NULL,
    quotation_5 DECIMAL(13,2) DEFAULT NULL,
    supplier_qty_1 INT DEFAULT NULL,
    supplier_qty_2 INT DEFAULT NULL,
    supplier_qty_3 INT DEFAULT NULL,
    supplier_qty_4 INT DEFAULT NULL,
    supplier_qty_5 INT DEFAULT NULL,
    supplier_name_1 VARCHAR(255) DEFAULT NULL,
    supplier_name_2 VARCHAR(255) DEFAULT NULL,
    supplier_name_3 VARCHAR(255) DEFAULT NULL,
    supplier_name_4 VARCHAR(255) DEFAULT NULL,
    supplier_name_5 VARCHAR(255) DEFAULT NULL,
    lowest_price DECIMAL(13,2) DEFAULT NULL,
    average_price DECIMAL(13,2) DEFAULT NULL,
    status VARCHAR(50) DEFAULT 'Pending',
    analysis TEXT DEFAULT NULL,
    report_link VARCHAR(255) DEFAULT NULL,
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    FOREIGN KEY (supplier_id) REFERENCES companies(company_id) ON DELETE SET NULL,
    FOREIGN KEY (supplier_id_1) REFERENCES companies(company_id) ON DELETE SET NULL,
    FOREIGN KEY (supplier_id_2) REFERENCES companies(company_id) ON DELETE SET NULL,
    FOREIGN KEY (supplier_id_3) REFERENCES companies(company_id) ON DELETE SET NULL,
    FOREIGN KEY (supplier_id_4) REFERENCES companies(company_id) ON DELETE SET NULL,
    FOREIGN KEY (supplier_id_5) REFERENCES companies(company_id) ON DELETE SET NULL
) ENGINE=InnoDB;

CREATE TABLE IF NOT EXISTS ppmp_plans (
    ppmp_id INT AUTO_INCREMENT PRIMARY KEY,
    project_name VARCHAR(255) NOT NULL,
    category VARCHAR(50) DEFAULT 'Other',
    budget DECIMAL(14,2) DEFAULT NULL,
    procurement_method VARCHAR(100) DEFAULT NULL,
    implementation_year SMALLINT DEFAULT NULL,
    end_user_unit VARCHAR(255) DEFAULT NULL,
    status VARCHAR(50) DEFAULT 'Pending',
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
) ENGINE=InnoDB;

CREATE TABLE IF NOT EXISTS dashboard_settings (
    setting_id INT AUTO_INCREMENT PRIMARY KEY,
    setting_key VARCHAR(100) NOT NULL UNIQUE,
    setting_value TEXT,
    updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP
) ENGINE=InnoDB;

CREATE TABLE IF NOT EXISTS procurement_reports (
    report_id INT AUTO_INCREMENT PRIMARY KEY,
    project_name VARCHAR(255) NOT NULL,
    document_type VARCHAR(100) DEFAULT NULL,
    status VARCHAR(50) DEFAULT 'Pending',
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
) ENGINE=InnoDB;

